1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { mailAttachmentUrl, type MessageFull, type MailFolder } from "@/lib/mail/types";
5	import {
6	  Icon,
7	  initials,
8	  displayName,
9	  avatarGradient,
10	  fullDate,
11	  joinAddresses,
12	  fmtBytesShort,
13	} from "./util";
14	
15	export function ReadingPane({
16	  message,
17	  loading,
18	  folders,
19	  currentFolder,
20	  mailboxAddress,
21	  onReply,
22	  onReplyAll,
23	  onForward,
24	  onArchive,
25	  onDelete,
26	  onMove,
27	  onToggleStar,
28	  onQuickReply,
29	  onBack,
30	}: {
31	  message: MessageFull | null;
32	  loading: boolean;
33	  folders: MailFolder[];
34	  currentFolder: string;
35	  /**
36	   * The mailbox this message was read from. Passed on to the attachment route:
37	   * without it the route falls back to the account's default mailbox and can
38	   * return a different message's file (see `mailAttachmentUrl`).
39	   */
40	  mailboxAddress?: string;
41	  onReply: () => void;
42	  onReplyAll: () => void;
43	  onForward: () => void;
44	  onArchive: () => void;
45	  onDelete: () => void;
46	  onMove: (toFolder: string) => void;
47	  onToggleStar: () => void;
48	  onQuickReply: (text: string) => Promise<void>;
49	  onBack: () => void;
50	}) {
51	  const [moveOpen, setMoveOpen] = useState(false);
52	  const [quick, setQuick] = useState("");
53	  const [sending, setSending] = useState(false);
54	
55	  useEffect(() => {
56	    setQuick("");
57	    setMoveOpen(false);
58	  }, [message?.uid, message?.folder]);
59	
60	  if (loading) return <ReadingSkeleton onBack={onBack} />;
61	
62	  if (!message) {
63	    return (
64	      <div className="flex h-full flex-col items-center justify-center px-6 text-center">
65	        <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-5 text-brand-300">
66	          <Icon.mail size={34} />
67	        </div>
68	        <p className="text-base font-semibold text-slate-200">Select a message</p>
69	        <p className="mt-1 max-w-xs text-sm text-slate-500">
70	          Pick a conversation from the list to read it here.
71	        </p>
72	      </div>
73	    );
74	  }
75	
76	  const submitQuick = async () => {
77	    const text = quick.trim();
78	    if (!text || sending) return;
79	    setSending(true);
80	    try {
81	      await onQuickReply(text);
82	      setQuick("");
83	    } finally {
84	      setSending(false);
85	    }
86	  };
87	
88	  const moveTargets = folders.filter((f) => f.path !== currentFolder);
89	
90	  return (
91	    <div className="flex h-full flex-col">
92	      {/* Toolbar */}
93	      <div className="flex flex-wrap items-center gap-1 border-b border-white/[0.06] px-3 py-2.5">
94	        <button onClick={onBack} className="btn-ghost mr-1 rounded-lg p-2 lg:hidden" aria-label="Back to list">
95	          <Icon.chevronLeft size={18} />
96	        </button>
97	        <ToolBtn label="Archive" onClick={onArchive}><Icon.archive size={17} /></ToolBtn>
98	        <ToolBtn label="Delete" onClick={onDelete} danger><Icon.trash size={17} /></ToolBtn>
99	        <ToolBtn label="Snooze" disabled title="Snooze — coming soon"><Icon.clock size={17} /></ToolBtn>
100	
101	        {/* Move dropdown */}
102	        <div className="relative">
103	          <ToolBtn label="Move" onClick={() => setMoveOpen((v) => !v)}><Icon.move size={17} /></ToolBtn>
104	          {moveOpen && (
105	            <>
106	              <div className="fixed inset-0 z-10" onClick={() => setMoveOpen(false)} />
107	              {/* Solid, not `glass` — a translucent menu over the message body
108	                  is unreadable (same fix as the mailbox switcher). */}
109	              <div className="absolute left-0 top-11 z-30 max-h-72 w-56 overflow-y-auto rounded-xl border border-white/15 bg-navy-900 py-1.5 shadow-2xl shadow-black/60 ring-1 ring-black/30">
110	                <p className="section-label border-b border-white/10 px-3 pb-1.5 pt-1">Move to</p>
111	                {moveTargets.map((f) => (
112	                  <button
113	                    key={f.path}
114	                    onClick={() => {
115	                      setMoveOpen(false);
116	                      onMove(f.path);
117	                    }}
118	                    className="flex w-full items-center gap-2.5 px-3 py-2 text-left text-sm text-slate-300 hover:bg-white/[0.05] hover:text-white"
119	                  >
120	                    <Icon.folder size={15} className="text-slate-500" />
121	                    <span className="truncate">{f.name}</span>
122	                  </button>
123	                ))}
124	              </div>
125	            </>
126	          )}
127	        </div>
128	
129	        <div className="mx-1 h-6 w-px bg-white/[0.08]" />
130	
131	        <ToolBtn label="Reply" onClick={onReply}><Icon.reply size={17} /></ToolBtn>
132	        <ToolBtn label="Reply all" onClick={onReplyAll}><Icon.replyAll size={17} /></ToolBtn>
133	        <ToolBtn label="Forward" onClick={onForward}><Icon.forward size={17} /></ToolBtn>
134	
135	        <button
136	          onClick={onToggleStar}
137	          className={`btn-ghost ml-auto rounded-lg p-2 ${message.flagged ? "text-amber-400" : ""}`}
138	          aria-label={message.flagged ? "Unstar" : "Star"}
139	        >
140	          {message.flagged ? <Icon.starFilled size={17} /> : <Icon.star size={17} />}
141	        </button>
142	      </div>
143	
144	      {/* Scroll body */}
145	      <div className="flex-1 overflow-y-auto">
146	        <div className="px-5 py-5 sm:px-7">
147	          <h1 className="text-xl font-bold leading-snug tracking-tight text-white sm:text-2xl">
148	            {message.subject || "(no subject)"}
149	          </h1>
150	
151	          {/* Sender line */}
152	          <div className="mt-4 flex items-start gap-3">
153	            <div
154	              className={`flex h-11 w-11 flex-none items-center justify-center rounded-full bg-gradient-to-br text-sm font-bold text-white ${avatarGradient(
155	                message.from.address
156	              )}`}
157	            >
158	              {initials(message.from)}
159	            </div>
160	            <div className="min-w-0 flex-1">
161	              <div className="flex flex-wrap items-baseline gap-x-2">
162	                <span className="text-sm font-semibold text-white">{displayName(message.from)}</span>
163	                <span className="truncate text-xs text-slate-500">&lt;{message.from.address}&gt;</span>
164	              </div>
165	              <p className="mt-0.5 text-xs text-slate-500">
166	                to {joinAddresses(message.to)}
167	                {message.cc.length > 0 && <>, cc {joinAddresses(message.cc)}</>}
168	              </p>
169	            </div>
170	            <span className="flex-none whitespace-nowrap pt-0.5 text-xs text-slate-500">
171	              {fullDate(message.date)}
172	            </span>
173	          </div>
174	
175	          {/* Attachments */}
176	          {message.attachments.length > 0 && (
177	            <div className="mt-4 flex flex-wrap gap-2">
178	              {message.attachments.map((att) => (
179	                <a
180	                  key={att.id}
181	                  href={mailAttachmentUrl({
182	                    folder: message.folder,
183	                    uid: message.uid,
184	                    part: att.id,
185	                    mailbox: mailboxAddress,
186	                  })}
187	                  className="group flex items-center gap-2.5 rounded-xl border border-white/10 bg-white/[0.03] px-3 py-2 text-sm transition-colors hover:border-brand-500/30 hover:bg-white/[0.06]"
188	                >
189	                  <span className="text-brand-300">
190	                    <Icon.paperclip size={16} />
191	                  </span>
192	                  <span className="min-w-0">
193	                    <span className="block max-w-[12rem] truncate text-slate-200 group-hover:text-white">{att.filename}</span>
194	                    <span className="block text-[11px] text-slate-500">{fmtBytesShort(att.sizeBytes)}</span>
195	                  </span>
196	                </a>
197	              ))}
198	            </div>
199	          )}
200	
201	          <div className="divider" />
202	
203	          {/* Body */}
204	          <MessageBody html={message.html} text={message.text} />
205	        </div>
206	      </div>
207	
208	      {/* Quick reply */}
209	      <div className="border-t border-white/[0.06] bg-navy-900/40 p-3">
210	        <div className="flex items-end gap-2 rounded-xl border border-white/10 bg-navy-900/80 p-2 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
211	          <div className={`hidden h-8 w-8 flex-none items-center justify-center rounded-full bg-gradient-to-br text-xs font-bold text-white sm:flex ${avatarGradient(message.from.address)}`}>
212	            <Icon.reply size={15} />
213	          </div>
214	          <textarea
215	            value={quick}
216	            onChange={(e) => setQuick(e.target.value)}
217	            onKeyDown={(e) => {
218	              if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
219	                e.preventDefault();
220	                void submitQuick();
221	              }
222	            }}
223	            rows={1}
224	            placeholder={`Quick reply to ${displayName(message.from)}…`}
225	            className="max-h-32 min-h-[2.25rem] flex-1 resize-none bg-transparent py-1.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
226	          />
227	          <button
228	            onClick={submitQuick}
229	            disabled={!quick.trim() || sending}
230	            className="btn-primary flex-none px-3 py-2"
231	          >
232	            {sending ? "Sending…" : "Send"}
233	          </button>
234	        </div>
235	        <p className="mt-1 px-1 text-[11px] text-slate-600">
236	          Press <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span> to send
237	        </p>
238	      </div>
239	    </div>
240	  );
241	}
242	
243	/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
244	 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
245	 *  reach cookies/storage. Plaintext falls back to a pre block. */
246	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
247	  const ref = useRef<HTMLIFrameElement>(null);
248	  const [height, setHeight] = useState(320);
249	
250	  const doc = html
251	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
252	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
253	        body{padding:16px;}
254	        img{max-width:100%;height:auto;}
255	        a{color:#5f2ee8;}
256	        table{max-width:100%;}
257	        pre{white-space:pre-wrap;}
258	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
259	      </style></head><body>${html}</body></html>`
260	    : null;
261	
262	  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
263	  // grow to a comfortable default and let the iframe scroll for very tall mail.
264	  useEffect(() => {
265	    setHeight(html ? 480 : 0);
266	  }, [html]);
267	
268	  // Render the body from a blob: URL rather than `srcDoc`. A `sandbox=""` srcdoc
269	  // frame loads as `about:srcdoc`, which our strict CSP `frame-src` refuses
270	  // ("This content is blocked…"). A blob: URL is a real same-origin URL that
271	  // `frame-src blob:` matches, so the frame loads; it still inherits the app CSP
272	  // (img-src https: lets email images through, scripts stay blocked) and stays
273	  // fully sandboxed. Revoked when the body changes / unmounts.
274	  const [bodyUrl, setBodyUrl] = useState<string | null>(null);
275	  useEffect(() => {
276	    if (!doc) {
277	      setBodyUrl(null);
278	      return;
279	    }
280	    const url = URL.createObjectURL(new Blob([doc], { type: "text/html" }));
281	    setBodyUrl(url);
282	    return () => URL.revokeObjectURL(url);
283	  }, [doc]);
284	
285	  if (doc && bodyUrl) {
286	    return (
287	      <iframe
288	        ref={ref}
289	        sandbox=""
290	        src={bodyUrl}
291	        title="Message content"
292	        className="w-full rounded-xl border border-white/[0.06] bg-white"
293	        style={{ height }}
294	      />
295	    );
296	  }
297	
298	  if (text && text.trim()) {
299	    return (
300	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
301	        {text}
302	      </pre>
303	    );
304	  }
305	
306	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
307	}
308	
309	function ToolBtn({
310	  children,
311	  label,
312	  onClick,
313	  danger,
314	  disabled,
315	  title,
316	}: {
317	  children: React.ReactNode;
318	  label: string;
319	  onClick?: () => void;
320	  danger?: boolean;
321	  disabled?: boolean;
322	  title?: string;
323	}) {
324	  return (
325	    <button
326	      onClick={onClick}
327	      disabled={disabled}
328	      title={title ?? label}
329	      aria-label={label}
330	      className={`inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-sm font-medium transition-colors ${
331	        disabled
332	          ? "cursor-not-allowed text-slate-600"
333	          : danger
334	          ? "text-slate-400 hover:bg-red-500/10 hover:text-red-300"
335	          : "text-slate-400 hover:bg-white/[0.06] hover:text-white"
336	      }`}
337	    >
338	      {children}
339	      <span className="hidden xl:inline">{label}</span>
340	    </button>
341	  );
342	}
343	
344	function ReadingSkeleton({ onBack }: { onBack: () => void }) {
345	  return (
346	    <div className="flex h-full flex-col">
347	      <div className="flex items-center gap-1 border-b border-white/[0.06] px-3 py-2.5">
348	        <button onClick={onBack} className="btn-ghost rounded-lg p-2 lg:hidden">
349	          <Icon.chevronLeft size={18} />
350	        </button>
351	        <div className="skeleton h-7 w-24" />
352	      </div>
353	      <div className="space-y-4 px-7 py-6">
354	        <div className="skeleton h-7 w-2/3" />
355	        <div className="flex gap-3">
356	          <div className="skeleton h-11 w-11 rounded-full" />
357	          <div className="flex-1 space-y-2">
358	            <div className="skeleton h-3.5 w-40" />
359	            <div className="skeleton h-3 w-28" />
360	          </div>
361	        </div>
362	        <div className="space-y-2.5 pt-4">
363	          <div className="skeleton h-3.5 w-full" />
364	          <div className="skeleton h-3.5 w-11/12" />
365	          <div className="skeleton h-3.5 w-4/5" />
366	          <div className="skeleton h-3.5 w-full" />
367	          <div className="skeleton h-3.5 w-3/4" />
368	        </div>
369	      </div>
370	    </div>
371	  );
372	}
