1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
4	import type {
5	  MailFolder,
6	  MailboxInfo,
7	  ListResult,
8	  MessageSummary,
9	  MessageFull,
10	  SendPayload,
11	} from "@/lib/mail/types";
12	import {
13	  listFolders,
14	  listMessages,
15	  getMessage,
16	  getMailboxes,
17	  sendMessage,
18	  setFlag,
19	  moveMessage,
20	  deleteMessage,
21	} from "@/lib/actions-mail";
22	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
23	import { FolderRail, MiniRail, type RailItem } from "./FolderRail";
24	import { MessageList } from "./MessageList";
25	import { ReadingPane } from "./ReadingPane";
26	import { ContactPanel } from "./ContactPanel";
27	import { useCompose, MAIL_SENT_EVENT } from "./ComposeProvider";
28	import { MailSettings } from "./MailSettings";
29	import { ShortcutHelp } from "./ShortcutHelp";
30	import { Icon, displayName, categoryOf, type MailTab } from "./util";
31	
32	const STARRED = "__starred__";
33	const SNOOZED = "__snoozed__";
34	
35	/** Per-mailbox signature config used when composing. */
36	type SigConfig = {
37	  enabled: boolean;
38	  onReply: boolean;
39	  placement: "above" | "below";
40	  plain: string; // plain-text fallback / derived text part
41	  html: string; // sanitized rich-signature HTML
42	};
43	
44	const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
45	  inbox: { label: "Inbox", icon: "inbox", order: 0 },
46	  sent: { label: "Sent", icon: "sent", order: 3 },
47	  drafts: { label: "Drafts", icon: "draft", order: 4 },
48	  junk: { label: "Spam", icon: "spam", order: 5 },
49	  trash: { label: "Trash", icon: "trash", order: 6 },
50	  archive: { label: "Archive", icon: "archive", order: 7 },
51	};
52	
53	export function MailClient({
54	  initialFolders,
55	  initialMailboxes,
56	  initialList,
57	  initialFolderPath,
58	  initialSignature = "",
59	  initialActiveAddress,
60	  loadMailboxes = getMailboxes,
61	}: {
62	  initialFolders: MailFolder[];
63	  initialMailboxes: MailboxInfo[];
64	  initialList: ListResult;
65	  initialFolderPath: string;
66	  initialSignature?: string;
67	  /**
68	   * How the switcher (re)loads the mailbox list. Defaults to the customer's own
69	   * mailboxes (`getMailboxes`); the admin company-inbox passes a company-scoped
70	   * loader so the two lists never bleed into each other.
71	   */
72	  loadMailboxes?: () => Promise<MailboxInfo[]>;
73	  /**
74	   * Mailbox the server already loaded folders and messages for (the `?mailbox=`
75	   * deep link from a mailbox row on the Business Email page). It MUST match what
76	   * the server rendered: seeding this from anything else would show one
77	   * mailbox's messages under another mailbox's name until the first refetch.
78	   * The server only sets it after confirming the address belongs to this user.
79	   */
80	  initialActiveAddress?: string;
81	}) {
82	  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
83	  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
84	  const [activeAddress, setActiveAddress] = useState<string | undefined>(
85	    initialActiveAddress ?? initialMailboxes[0]?.address,
86	  );
87	  const [selected, setSelected] = useState<string>(initialFolderPath);
88	  const [list, setList] = useState<ListResult>(initialList);
89	  const [page, setPage] = useState(1);
90	  const [tab, setTab] = useState<MailTab>("primary");
91	  const [search, setSearch] = useState("");
92	
93	  const [selectedUid, setSelectedUid] = useState<number | null>(null);
94	  const [cursorUid, setCursorUid] = useState<number | null>(null);
95	  const [message, setMessage] = useState<MessageFull | null>(null);
96	  const [msgLoading, setMsgLoading] = useState(false);
97	
98	  // The composer lives at the shell level (ComposeProvider) so it stays mounted —
99	  // and its in-progress draft survives — across navigation to other dashboard
100	  // pages, and so `position: fixed` resolves to the real viewport. We drive it
101	  // purely through this context instead of rendering <Composer> inline.
102	  const compose = useCompose();
103	  const [sig, setSig] = useState<SigConfig>({
104	    enabled: true,
105	    onReply: true,
106	    placement: "below",
107	    plain: initialSignature,
108	    html: "",
109	  });
110	  const [showSettings, setShowSettings] = useState(false);
111	  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
112	  const [railOpen, setRailOpen] = useState(false);
113	  const [refreshing, setRefreshing] = useState(false);
114	  const [toast, setToast] = useState<string | null>(null);
115	  const [showHelp, setShowHelp] = useState(false);
116	
117	  // Collapsible panels — desktop only, persisted so the layout choice sticks.
118	  const [railCollapsed, setRailCollapsed] = useState(false);
119	  const [contactCollapsed, setContactCollapsed] = useState(false);
120	  useEffect(() => {
121	    try {
122	      if (localStorage.getItem("nxeon.mail.railCollapsed") === "1") setRailCollapsed(true);
123	      if (localStorage.getItem("nxeon.mail.contactCollapsed") === "1") setContactCollapsed(true);
124	    } catch {}
125	  }, []);
126	  const toggleRail = useCallback(() => {
127	    setRailCollapsed((v) => {
128	      const next = !v;
129	      try { localStorage.setItem("nxeon.mail.railCollapsed", next ? "1" : "0"); } catch {}
130	      return next;
131	    });
132	  }, []);
133	  const toggleContact = useCallback(() => {
134	    setContactCollapsed((v) => {
135	      const next = !v;
136	      try { localStorage.setItem("nxeon.mail.contactCollapsed", next ? "1" : "0"); } catch {}
137	      return next;
138	    });
139	  }, []);
140	
141	  const [listPending, startList] = useTransition();
142	  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
143	
144	  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;
145	
146	  /* ---- Signature config (loaded per active mailbox) --------------------- */
147	  const loadSig = useCallback((addr?: string) => {
148	    getMailboxSettings(addr)
149	      .then((s) =>
150	        setSig({
151	          enabled: s.signatureEnabled,
152	          onReply: s.signatureOnReply,
153	          placement: s.signaturePlacement,
154	          plain: s.signature,
155	          html: s.signatureHtml,
156	        }),
157	      )
158	      .catch(() => {});
159	  }, []);
160	
161	  useEffect(() => {
162	    loadSig(activeAddress);
163	  }, [activeAddress, loadSig]);
164	
165	  /** Signature fields to spread into a compose draft, honouring the toggles. */
166	  const sigFields = useCallback(
167	    (isReply: boolean) => {
168	      if (!sig.enabled) return {};
169	      if (isReply && !sig.onReply) return {};
170	      return {
171	        signature: sig.plain || undefined,
172	        signatureHtml: sig.html || undefined,
173	        signaturePlacement: sig.placement,
174	      };
175	    },
176	    [sig],
177	  );
178	
179	  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
180	  const archivePath = folders.find((f) => f.role === "archive")?.path;
181	  const trashPath = folders.find((f) => f.role === "trash")?.path;
182	
183	  /* ---- Rail model ------------------------------------------------------- */
184	  const byRole = (role: string) => folders.find((f) => f.role === role);
185	  const primaryItems: RailItem[] = [];
