// Autosize: with sandbox="allow-same-origin" (and still NO allow-scripts, so
// sender scripts stay inert) the parent can read the inner document and grow the
// frame to its full content height — the whole email renders in the page flow
// (the reading pane scrolls, the frame itself never does), so tall mail is no
// longer clipped. Reset to the min height when the body changes.
useEffect(() => {
  setHeight(html ? MIN_BODY_HEIGHT : 0);
}, [html]);

// Measure the rendered document and size the frame to it (plus a small buffer),
// clamped so short mail isn't a giant box and runaway content can't explode.
const measure = useCallback(() => {
  const cdoc = ref.current?.contentDocument;
  if (!cdoc) return;
  const h = Math.max(
    cdoc.documentElement?.scrollHeight ?? 0,
    cdoc.body?.scrollHeight ?? 0,
  );
  if (h > 0) {
    setHeight(Math.min(MAX_BODY_HEIGHT, Math.max(MIN_BODY_HEIGHT, Math.ceil(h) + BODY_HEIGHT_BUFFER)));
  }
}, []);

// Tear down the body observer on unmount / body swap.
useEffect(() => () => { observerRef.current?.disconnect(); observerRef.current = null; }, []);

// On each (re)load: measure once, then keep re-measuring as late layout settles
// — image decode, web-font swaps, async reflows. A ResizeObserver on the inner
// <body> catches most of it; a few delayed passes and per-image load handlers
// cover the rest.
const handleLoad = useCallback(() => {
  measure();
  const cdoc = ref.current?.contentDocument;
  [60, 200, 500, 1200].forEach((ms) => window.setTimeout(measure, ms));
  observerRef.current?.disconnect();
  observerRef.current = null;
  if (cdoc?.body && typeof ResizeObserver !== "undefined") {
    const ro = new ResizeObserver(() => measure());
    ro.observe(cdoc.body);
    observerRef.current = ro;
  }
  cdoc?.querySelectorAll("img").forEach((img) => {
    if (!img.complete) img.addEventListener("load", measure, { once: true });
  });
}, [measure]);

